using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.TKT.TicketsUsuariosAsignados;namespace GraphApi.Services.TKT.TicketsUsuariosAsignados{    public class TicketsUsuariosAsignadosService : ITicketsUsuariosAsignadosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TicketsUsuariosAsignadosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTicketsUsuariosAsignados>> GetTicketsUsuariosAsignados(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM tkt.vsTicketsUsuariosAsignados (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTicketsUsuariosAsignados>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTicketsUsuariosAsignadosDynamic(            int? ticketsUsuariosAsignadosID,            int? ticketID,            string? tituloTicket,            int? usuarioID,            string? usuarioAsignado,            bool? terminado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TicketsUsuariosAsignadosID, TicketID, TituloTicket, UsuarioID, UsuarioAsignado, Terminado, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM tkt.vsTicketsUsuariosAsignados (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (ticketsUsuariosAsignadosID.HasValue)            {                vSql.Append(" AND TicketsUsuariosAsignadosID = @TicketsUsuariosAsignadosID");                vParameters.Add("TicketsUsuariosAsignadosID",ticketsUsuariosAsignadosID);            }            if (!string.IsNullOrWhiteSpace(tituloTicket))            {                vSql.Append(" AND TituloTicket LIKE @TituloTicket");                vParameters.Add("TituloTicket",$"%{tituloTicket}%");            }            if (!string.IsNullOrWhiteSpace(usuarioAsignado))            {                vSql.Append(" AND UsuarioAsignado LIKE @UsuarioAsignado");                vParameters.Add("UsuarioAsignado",$"%{usuarioAsignado}%");            }            if (terminado.HasValue)            {                vSql.Append(" AND Terminado = @Terminado");                vParameters.Add("Terminado", terminado.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTicketsUsuariosAsignados> CreateTicketsUsuariosAsignados(clCreateTicketsUsuariosAsignados objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO tkt.TicketsUsuariosAsignados                (TicketID, UsuarioID, Terminado, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TicketID, @UsuarioID, @Terminado, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TicketID,                objInput.UsuarioID,                objInput.Terminado,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TicketsUsuariosAsignadosID, TicketID, TituloTicket, UsuarioID, UsuarioAsignado, Terminado, bEliminado                FROM tkt.vsTicketsUsuariosAsignados (NOLOCK)                WHERE TicketsUsuariosAsignadosID = @TicketsUsuariosAsignadosID;";            var vReadParams = new { TicketsUsuariosAsignadosID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTicketsUsuariosAsignados>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el TicketsUsuariosAsignado con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTicketsUsuariosAsignados?> UpdateTicketsUsuariosAsignados(clUpdateTicketsUsuariosAsignados objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TicketsUsuariosAsignadosID", objInput.TicketsUsuariosAsignadosID);            if (objInput.TicketID != null)            {                vSets.Add("TicketID = @TicketID");                vParameters.Add("TicketID", objInput.TicketID);            }            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.Terminado != null)            {                vSets.Add("Terminado = @Terminado");                vParameters.Add("Terminado", objInput.Terminado);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE tkt.TicketsUsuariosAsignados                SET {vSetClause}                WHERE TicketsUsuariosAsignadosID = @TicketsUsuariosAsignadosID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TicketsUsuariosAsignadosID, TicketID, TituloTicket, UsuarioID, UsuarioAsignado, Terminado, bEliminado                FROM tkt.vsTicketsUsuariosAsignados (NOLOCK)                WHERE TicketsUsuariosAsignadosID = @TicketsUsuariosAsignadosID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTicketsUsuariosAsignados>(sSelect, new {  objInput.TicketsUsuariosAsignadosID });        }        public async Task<bool> DeleteTicketsUsuariosAsignados(int nTicketsUsuariosAsignadosID)        {            const string sSql = @"                DELETE FROM tkt.TicketsUsuariosAsignados                WHERE TicketsUsuariosAsignadosID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTicketsUsuariosAsignadosID });            return vAffected > 0;        }    }}